// Normalize the error into a structured log event.
// Never log secrets; only metadata we control.
const e = $json;
const redact = (s = '') => String(s).replace(/(sk-[A-Za-z0-9-]{6})[A-Za-z0-9-]+/g, '$1***').slice(0, 2000);
return [{
  json: {
    level: 'error',
    ts: new Date().toISOString(),
    workflow: e.workflow?.name || 'unknown',
    workflowId: e.workflow?.id || null,
    execution: e.execution?.id || null,
    node: e.execution?.lastNodeExecuted || null,
    message: redact(e.execution?.error?.message || e.error?.message || 'Unknown error'),
    stack: redact(e.execution?.error?.stack || '')
  }
}];
